select f.folio_ingreso, f.folio_proveedor, pr.razon_social as proveedor, cap.nombre as capitulo, pa.cuenta_finat,
       f.importe_factura, f.periodo_inicio, f.es_pasivo, f.cr_contrarecibo, f.fecha_pago, f.origen_migracion is not null as alta_manual,
       f.created_at::date as capturada_el
from facturas f
join capitulos cap on cap.id = f.capitulo_id
join partidas pa on pa.id = f.partida_id
left join proveedores pr on pr.id = f.proveedor_id
where f.anulada = false and f.estatus_general = 'gasto_reflejado'
  and not exists (select 1 from pagados p where p.cr = ltrim(btrim(coalesce(f.cr_contrarecibo, '')), '0'))
order by cap.nombre, pa.cuenta_finat, pr.razon_social, f.folio_proveedor;